# CDI public delta feed. Only signed-in maintainers publish the public channel.
# Source repository stays private; public channel contains exact small patches.
PUBLIC_FEED_URL = ("https://raw.githubusercontent.com/HenrryCDI/"
                   "royyal-releases/main/cdi-consulta-historica/stable.json")

def _get_feed():
    from urllib.request import Request, urlopen
    request = Request(PUBLIC_FEED_URL, headers={"User-Agent": "CDI-Consulta-Historica-Updater/1"})
    try:
        with urlopen(request, timeout=18) as response:
            raw = response.read(262145)
    except Exception as exc:
        raise UpdateError("Canal publico do GitHub indisponivel. Verifique a internet.") from exc
    if len(raw) > 262144:
        raise UpdateError("Manifesto publico acima do limite.")
    try:
        feed = json.loads(raw.decode("utf-8"))
    except (ValueError, UnicodeDecodeError) as exc:
        raise UpdateError("Manifesto publico invalido.") from exc
    if not isinstance(feed, dict) or feed.get("schema") != 1 or feed.get("channel") != "stable":
        raise UpdateError("Canal de atualizacao desconhecido.")
    return feed

def _apply_operations(contents, operations, rel):
    if not isinstance(operations, list) or len(operations) > 24:
        raise UpdateError("Instrucoes invalidas: " + rel)
    try:
        result = contents.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise UpdateError("Arquivo nao textual: " + rel) from exc
    for entry in operations:
        if not isinstance(entry, dict) or entry.get("op") not in ("replace", "append"):
            raise UpdateError("Operacao desconhecida: " + rel)
        if entry["op"] == "replace":
            old, new = entry.get("old"), entry.get("new")
            if not isinstance(old, str) or not isinstance(new, str) or not old or result.count(old) != 1:
                raise UpdateError("Diferenca inesperada no arquivo: " + rel)
            result = result.replace(old, new, 1)
        else:
            value = entry.get("value")
            if not isinstance(value, str) or not value or len(value) > 45000:
                raise UpdateError("Anexo invalido: " + rel)
            result += value
    return result.encode("utf-8")

def stage_update(target, git_binary="git", repo=REPO, branch=BRANCH, subdir=SUBDIR, base=None):
    """No Git executable or GitHub login is needed. Reconstruct from verified deltas."""
    target = Path(target).resolve()
    old = local_version(target)
    version_tuple(old)
    feed = _get_feed()
    version = feed.get("version")
    if not isinstance(version, str):
        raise UpdateError("Versao publica ausente.")
    version_tuple(version)
    if version_tuple(version) <= version_tuple(old):
        return None
    manifest = feed.get("manifest")
    if not isinstance(manifest, dict) or manifest.get("version") != version:
        raise UpdateError("Manifesto de destino incoerente.")
    files = manifest.get("files")
    if not isinstance(files, dict) or set(files) != set(REQUIRED):
        raise UpdateError("Manifesto de destino incompleto.")
    upgrades = feed.get("upgrades")
    upgrade = upgrades.get(old) if isinstance(upgrades, dict) else None
    if not isinstance(upgrade, dict):
        raise UpdateError("Instalacao antiga sem rota direta. Use o pacote de migracao CDI.")
    base_hashes = upgrade.get("base_files")
    ops = upgrade.get("operations")
    if not isinstance(base_hashes, dict) or set(base_hashes) != set(REQUIRED) or not isinstance(ops, dict):
        raise UpdateError("Diferencas publicas incompletas.")
    if set(ops).difference(REQUIRED):
        raise UpdateError("Arquivo nao permitido na atualizacao.")
    if base is None:
        base = Path(os.environ.get("LOCALAPPDATA") or tempfile.gettempdir()) / "ModernizaReceitas" / "updates"
    base = Path(base)
    base.mkdir(parents=True, exist_ok=True)
    work = base / ("public_" + uuid.uuid4().hex)
    stage = work / "stage"
    try:
        stage.mkdir(parents=True)
        for rel in REQUIRED:
            original = target / rel
            if not original.is_file() or original.is_symlink():
                raise UpdateError("Instalacao incompleta: " + rel)
            expected_old = base_hashes[rel]
            if not isinstance(expected_old, str) or not re.fullmatch(r"[a-f0-9]{64}", expected_old):
                raise UpdateError("Hash de origem invalido: " + rel)
            if sha256_file(original) != expected_old:
                raise UpdateError("Arquivo local difere da versao oficial: " + rel)
            new_data = _apply_operations(original.read_bytes(), ops.get(rel, []), rel)
            dest = stage / rel
            dest.parent.mkdir(parents=True, exist_ok=True)
            dest.write_bytes(new_data)
            expected_new = files[rel]
            if not isinstance(expected_new, str) or not re.fullmatch(r"[a-f0-9]{64}", expected_new):
                raise UpdateError("Hash de destino invalido: " + rel)
            if sha256_file(dest) != expected_new:
                raise UpdateError("Integridade da atualizacao invalida: " + rel)
        (stage / "MANIFEST.json").write_text(
            json.dumps(manifest, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        inspect_manifest(stage)
        return {"stage": str(stage), "version": version, "old_version": old}
    except Exception:
        shutil.rmtree(work, ignore_errors=True)
        raise

