# Receita optica: busca todas as colunas textuais, numericas e datas realmente
# existentes. Os campos variam entre backups/edicoes do Moderniza.
# O nome da coluna vem EXCLUSIVAMENTE de sys.columns (nunca do HTTP).
_OPTICAL_TYPES = frozenset({
    'varchar','nvarchar','char','nchar','text','ntext','int','bigint',
    'smallint','tinyint','bit','decimal','numeric','money','smallmoney',
    'float','real','datetime','datetime2','smalldatetime','date',
    'time','uniqueidentifier',
})


def _optical_columns(con, table):
    if table not in ('objeto_ordem_servico_oticas', 'objeto_ordem_servico'):
        return []
    rows = run(con, """SELECT c.name AS coluna, tp.name AS tipo
       FROM sys.columns c JOIN sys.tables t ON t.object_id=c.object_id
       JOIN sys.schemas s ON s.schema_id=t.schema_id
       JOIN sys.types tp ON tp.user_type_id=c.user_type_id
       WHERE s.name=N'dbo' AND t.name=? ORDER BY c.column_id""", (table,))
    return [row['coluna'] for row in rows
            if str(row['tipo']).lower() in _OPTICAL_TYPES][:180]


def _optical_sql_name(value):
    # Apenas identificadores descobertos no esquema; ainda assim, escapar ].
    return '[' + value.replace(']', ']]') + ']'


def dados_opticos_completos(con, number):
    cols = _optical_columns(con, 'objeto_ordem_servico_oticas')
    if 'id_ordem_servico' not in cols:
        return []
    sql_cols = ','.join(_optical_sql_name(c) for c in cols)
    order = '[id_objeto]' if 'id_objeto' in cols else '[id_ordem_servico]'
    result = run(con, f"""SELECT TOP (100) {sql_cols}
        FROM dbo.objeto_ordem_servico_oticas
        WHERE id_ordem_servico=? ORDER BY {order}""", (number,))

    # Alguns backups armazenam campos gerais (incluindo descricao, observacoes
    # e entrega) na tabela pai do objeto. Consulta somente se existir a chave.
    parent_cols = _optical_columns(con, 'objeto_ordem_servico')
    if 'id_objeto' in parent_cols and any(row.get('id_objeto') is not None for row in result):
        select_parent = ','.join(_optical_sql_name(c) for c in parent_cols)
        for row in result:
            if row.get('id_objeto') is None:
                continue
            parent = run(con, f"""SELECT TOP (1) {select_parent}
                FROM dbo.objeto_ordem_servico WHERE id_objeto=?""",
                (row['id_objeto'],))
            if parent:
                for key, value in parent[0].items():
                    if key not in ('id_objeto', 'id_ordem_servico'):
                        row.setdefault('objeto_' + key, value)
    return result


