 const name=key.replace(/^objeto_/,'').toLowerCase();
 if(/^(odl_|od_l_|od_longe_|longe_od_)/.test(name))return 'longeOD';
 if(/^(oel_|oe_l_|oe_longe_|longe_oe_)/.test(name))return 'longeOE';
