 if(/(entrega|previsao|entregue|usuario_entreg)/.test(name))return 'entrega';
 if(/(altura|pupila|pupilar|adicao|dnp|ponte|diametro|aro|medida|distancia|calcular)/.test(name))return 'medidas';
 if(/(receita|medico|laborat|prescr|validade|profissional)/.test(name))return 'receita';
 return 'adicionais';
}
function opticalValue(value){
 if(value==null||value==='')return 'Não informado';
 if(value===true)return 'Sim';
 if(value===false)return 'Não';
 if(typeof value==='string'&&/^\d{4}-\d{2}-\d{2}(?:T00:00:00)?$/.test(value))return dateText(value);
 return String(value);
}
